<?php
namespace App\Notifications;
use Illuminate\Bus\Queueable; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
class WelcomeNotification extends Notification { use Queueable; public function __construct(public string $name, public string $kind='creator'){} public function via(object $notifiable):array{return ['mail'];} public function toMail(object $notifiable):MailMessage { $team=$this->kind==='agency'; return (new MailMessage)->subject($team?'Your Quick GIGS agency profile is ready':'Welcome to Quick GIGS, '.$this->name)->greeting('Welcome '.$this->name.'!')->line($team?'Your team can now add services and work references for admin review.':'Your account is ready. Verify your email, complete your profile and get started.')->line('There are no creator listing, bidding or platform fees.')->action($team?'Open your team profile':($this->kind==='business'?'Open your workspace':'Open your studio'), route($this->kind==='business'?'business.home':'creator.dashboard')); } }
